import i18n from "@/i18n";
import { NODE_DEFAULT_SIZE } from "@/constant/canvas";
import type { CanvasAgentOp } from "@/lib/canvas/canvas-agent-ops";
import { audioMetadata, imageMetadata, videoMetadata } from "@/lib/canvas/canvas-node-factory";
import { fitNodeSize } from "@/lib/canvas/canvas-node-size";
import { randomId } from "@/lib/utils";
import { fetchLocalAssetFile, postState, validateLocalAssetImport, type AgentLocalAsset } from "@/services/api/canvas-agent";
import { deleteStoredImages, uploadImage } from "@/services/image-storage";
import { deleteStoredMedia, uploadMediaFile } from "@/services/file-storage";
import type { AgentCanvasContext } from "@/stores/use-agent-store";
import { CanvasNodeType } from "@/types/canvas";

/** 复用媒体上传和画布批量建节点流程，所有文件就绪后一次落入原目标画布。 */
export async function importLocalAssetNodes(endpoint: string, token: string, clientId: string, requestId: string, input: Record<string, unknown>, getContext: () => AgentCanvasContext | null) {
    const projectId = String(input.projectId || "");
    const context = () => {
        const current = getContext();
        if (!current || current.snapshot.projectId !== projectId) throw new Error(i18n.t("agent.localAssets.canvasChanged"));
        return current;
    };
    context();
    const assets = input.assets as AgentLocalAsset[];
    if (!Array.isArray(assets) || !assets.length) throw new Error(i18n.t("agent.localAssets.noAssets"));
    const images: string[] = [];
    const media: string[] = [];
    const ops: CanvasAgentOp[] = [];
    const nodes: Array<{ id: string; assetId: string; title: string; kind: AgentLocalAsset["kind"] }> = [];
    let offset = 0;
    try {
        for (const asset of assets) {
            context();
            const blob = await fetchLocalAssetFile(endpoint, token, clientId, requestId, asset.assetId);
            let size;
            let metadata;
            if (asset.kind === "image") {
                const image = await uploadImage(blob);
                if (image.storageKey) images.push(image.storageKey);
                size = fitNodeSize(image.width, image.height);
                metadata = imageMetadata(image);
            } else {
                const file = await uploadMediaFile(blob, asset.kind);
                media.push(file.storageKey);
                const spec = NODE_DEFAULT_SIZE[CanvasNodeType.Video];
                size = asset.kind === "video" ? fitNodeSize(file.width || 1280, file.height || 720, spec.width, spec.width) : NODE_DEFAULT_SIZE[CanvasNodeType.Audio];
                metadata = asset.kind === "video" ? videoMetadata(file) : audioMetadata(file);
            }
            const id = `${asset.kind}-${randomId()}`;
            ops.push({ type: "add_node", id, nodeType: asset.kind, title: asset.fileName, position: { x: Number(input.x) + offset, y: Number(input.y) }, width: size.width, height: size.height, metadata });
            nodes.push({ id, assetId: asset.assetId, title: asset.fileName, kind: asset.kind });
            offset += size.width + 40;
        }
        // 沿用既有工具请求超时；过期、撤销授权或切换画布后不能继续写入。
        await validateLocalAssetImport(endpoint, token, clientId, requestId);
        const snapshot = context().applyOps([...ops, { type: "select_nodes", ids: nodes.map((node) => node.id) }]);
        await postState(endpoint, token, clientId, snapshot);
        return { nodes };
    } catch (error) {
        await Promise.allSettled([deleteStoredImages(images), deleteStoredMedia(media)]);
        throw error;
    }
}

