function insertAfterUnreleased(file) {
  let text = fs.readFileSync(file, 'utf8');
  const idx = text.indexOf('## Unreleased');
  if (idx < 0) return 'NO ANCHOR ' + file;
  const after = idx + '## Unreleased'.length;
  const rest = text.slice(after);
  const m = rest.match(/^\r?\n+/) || [''];
  const nl = text.includes('\r\n') ? '\r\n' : '\n';
  const head = text.slice(0, idx) + '## Unreleased' + nl + rest.slice(0, m[0].length);
  const tail = rest.slice(m[0].length);
  fs.writeFileSync(file, head + add + nl + nl + tail, 'utf8');
  return 'OK ' + file;
}
